-- ── Article: les-phases-de-la-rupture-chez-l-homme ──
DO $$
DECLARE
  art_id UUID;
BEGIN
  -- Insert article
  INSERT INTO public.blog_articles (internal_slug, featured_image_url, author_id, status, published_at)
  VALUES ('les-phases-de-la-rupture-chez-l-homme', '/blog/phases-rupture-homme.webp', 'mathieu-courtin', 'published', '2026-02-21T00:00:00.000Z')
  ON CONFLICT (internal_slug) DO UPDATE SET
