  VALUES ('compatibilite-amoureuse-scorpion', '/blog/compatibilite-amoureuse-scorpion.svg', 'mathieu-courtin', 'published', '2026-03-03T00:00:00.000Z')
  ON CONFLICT (internal_slug) DO UPDATE SET
