  VALUES ('compatibilite-amoureuse-poissons', '/blog/compatibilite-amoureuse-poissons.svg', 'lucie-courtin', 'published', '2026-03-03T00:00:00.000Z')
  ON CONFLICT (internal_slug) DO UPDATE SET
    featured_image_url = EXCLUDED.featured_image_url,
